import json, sys, hashlib
from pathlib import Path
q=json.loads(Path(sys.argv[1]).read_text(encoding='utf-8')); op=q['op']; root=Path('.').resolve()
p=(root/q.get('path','sources/rules.md')).resolve()
if not p.is_relative_to(root): raise ValueError('outside fixture')
if op=='read':
    lines=p.read_text(encoding='utf-8').splitlines(); start=q.get('start',1); end=min(q.get('end',len(lines)),len(lines))
    result={'path':q['path'],'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'total_lines':len(lines),'start':start,'end':end,'text':'\n'.join(lines[start-1:end]),'truncated':start>1 or end<len(lines)}
elif op=='continue':
    request=q['request_id']; jobs=json.loads(Path('jobs.json').read_text(encoding='utf-8'))
    if request not in jobs: raise ValueError('unknown request_id')
    job=jobs[request]; result=job['result']; job['status']='completed';Path('jobs.json').write_text(json.dumps(jobs)+'\n',encoding='utf-8')
else: raise ValueError('unknown operation')
with Path('read-events.jsonl').open('a',encoding='utf-8') as f:f.write(json.dumps({'request':q,'result':result},ensure_ascii=False)+'\n')
print(json.dumps(result,ensure_ascii=False))

