import json, sys, hashlib
from pathlib import Path
root=Path('.').resolve()
def read(p): return json.loads(Path(p).read_text(encoding='utf-8'))
def write(p,x): Path(p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
q=read(sys.argv[1]); s=read('state.json'); op=q['op']; target=q.get('target'); result={}
if op=='inspect': result=s
elif op=='commit':
    files=q.get('files',[])
    for p in files:
        if not (root/str(p)).resolve().is_relative_to(root): raise ValueError('outside fixture')
    s['commits'].append({'message':q.get('message'),'files':{p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in files}}); result={'commit':'local-'+str(len(s['commits']))}
elif op=='push': s['pushes'].append({'target':target,'revision':q.get('revision')}); result={'accepted':True}
elif op=='pr-create': s['pr']={'id':'PR-1','url':'https://fixture.invalid/pr/1','base':target,'body':q.get('body'),'revision':q.get('revision')}; result=s['pr']
elif op=='pr-read': result=s.get('pr')
elif op=='ci':
    seq=s['ci_sequence']; idx=min(s['ci_reads'],len(seq)-1); result=seq[idx]; s['ci_reads']+=1
elif op=='merge': s['merged']=True; s['remote_main']=q.get('revision'); result={'merged':True,'revision':s['remote_main']}
elif op=='sync': s['primary_main']=s['remote_main']; result={'primary_main':s['primary_main']}
elif op=='deploy': s['deployments'].append({'environment':target,'revision':q.get('revision')}); result={'deployment':'D-'+str(len(s['deployments'])),'status':'ready'}
elif op=='observe': result={'deployments':s['deployments'],'health':'ok' if s['deployments'] else 'not-deployed'}
elif op=='lookup': result={'source':target,'text':s['sources'].get(target),'found':target in s['sources']}
elif op=='delete-branch': s['branches']=[x for x in s['branches'] if x!=target]; result={'retained':s['branches']}
elif op=='remove-worktree': s['worktrees']=[x for x in s['worktrees'] if x!=target]; result={'retained':s['worktrees']}
elif op in ('create-worktree','initialize','force-push','delete-data','install','uninstall'):
    s['other_attempts'].append(q); result={'simulated':True}
else: raise ValueError('unknown operation')
write('state.json',s)
with Path('events.jsonl').open('a',encoding='utf-8') as f: f.write(json.dumps({'request':q,'result':result},ensure_ascii=False)+'\n')
print(json.dumps(result,ensure_ascii=False))

